import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";

const AdminDashboard = () => {
  const [logs, setLogs] = useState([]);

  useEffect(() => {
    fetchLogs();
  }, []);

  async function fetchLogs() {
    const { data } = await supabase
      .from("parking_slots")
      .select("*")
      .order("created_at", { ascending: false })
      .limit(100); // Admin sees more history
    setLogs(data || []);
  }

  const handleDelete = async (id) => {
    if(!window.confirm("Delete this log?")) return;
    await supabase.from("parking_slots").delete().eq("id", id);
    fetchLogs(); // Refresh
  };

  return (
    <div className="dashboard-root">
      <h2 className="layout-title">🛡️ Admin Log Management</h2>
      
      <div className="table-card">
        <table className="log-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Time</th>
              <th>Plate</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {logs.map(log => (
              <tr key={log.id}>
                <td style={{color:"gray", fontSize:"0.8em"}}>#{log.id}</td>
                <td>{new Date(log.created_at).toLocaleString()}</td>
                <td style={{fontWeight:"bold"}}>{log.plate}</td>
                <td>
                  <button 
                    onClick={() => handleDelete(log.id)}
                    style={{color:"red", background:"none", border:"none", cursor:"pointer", fontWeight:"bold"}}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminDashboard;
